'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var format = require( '@stdlib/string/format' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var Float64Array = require( '@stdlib/array/float64' );
var Params = require( '@stdlib/ml/base/sgd/params/float64' );
var tryRequire = require( '@stdlib/utils/try-require' );
var pkg = require( './../package.json' ).name;


// VARIABLES //

var dsgdTrainer = tryRequire( resolve( __dirname, './../lib/ndarray.native.js' ) );
var opts = {
	'skip': ( dsgdTrainer instanceof Error )
};
var options = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {PositiveInteger} N - array length
* @returns {Function} benchmark function
*/
function createBenchmark( N ) {
	var ws = new Float64Array( N );
	var x = uniform( N*N, -10.0, 10.0, options );
	var y = uniform( N, -10.0, 10.0, options );
	var w = uniform( N, -0.05, 0.05, options );
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var params;
		var z;
		var i;

		params = new Params();

		params.penalty = 'l2';
		params.learningRate = 'constant';
		params.lossFunction = 'hinge';
		params.intercept = 0.0;
		params.maxIter = 500;
		params.penaltyParams = new Float64Array( [ 2.5, 0.0 ] );
		params.learningRateParams = new Float64Array( [ 0.01, 0.0 ] );
		params.lossFunctionParams = new Float64Array( [ 0.0 ] );
		params.fitIntercept = true;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dsgdTrainer( N, N, x, N, 1, 0, y, 1, 0, w, 1, 0, ws, 1, 0, params ); // eslint-disable-line max-len
			if ( isnan( z[ i%z.length ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( z[ i%z.length ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var min;
	var max;
	var N;
	var f;
	var i;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( i = min; i <= max; i++ ) {
		N = floor( pow( pow( 10, i ), 1.0/2.0 ) );
		f = createBenchmark( N );
		bench( format( '%s::native:ndarray:size=%d', pkg, N*N ), opts, f );
	}
}

main();
